# Disable App Access to Tracking Data Write-Host "Revoking app access to personal data..." -ForegroundColor Cyan $consentStore = "HKCU:\Software\Microsoft\Windows\CurrentVersion\CapabilityAccessManager\ConsentStore" # Deny app access to diagnostics $path = "$consentStore\appDiagnostics" if (-not (Test-Path $path)) { New-Item -Path $path -Force | Out-Null } Set-ItemProperty -Path $path -Name "Value" -Value "Deny" -Force -ErrorAction SilentlyContinue # Deny app access to contacts $path = "$consentStore\contacts" if (-not (Test-Path $path)) { New-Item -Path $path -Force | Out-Null } Set-ItemProperty -Path $path -Name "Value" -Value "Deny" -Force -ErrorAction SilentlyContinue # Deny app access to calendar $path = "$consentStore\appointments" if (-not (Test-Path $path)) { New-Item -Path $path -Force | Out-Null } Set-ItemProperty -Path $path -Name "Value" -Value "Deny" -Force -ErrorAction SilentlyContinue # Deny app access to call history $path = "$consentStore\phoneCallHistory" if (-not (Test-Path $path)) { New-Item -Path $path -Force | Out-Null } Set-ItemProperty -Path $path -Name "Value" -Value "Deny" -Force -ErrorAction SilentlyContinue # Deny app access to email $path = "$consentStore\email" if (-not (Test-Path $path)) { New-Item -Path $path -Force | Out-Null } Set-ItemProperty -Path $path -Name "Value" -Value "Deny" -Force -ErrorAction SilentlyContinue # Deny app access to tasks $path = "$consentStore\userDataTasks" if (-not (Test-Path $path)) { New-Item -Path $path -Force | Out-Null } Set-ItemProperty -Path $path -Name "Value" -Value "Deny" -Force -ErrorAction SilentlyContinue # Deny app access to messaging $path = "$consentStore\chat" if (-not (Test-Path $path)) { New-Item -Path $path -Force | Out-Null } Set-ItemProperty -Path $path -Name "Value" -Value "Deny" -Force -ErrorAction SilentlyContinue # Deny app access to phone calls $path = "$consentStore\phoneCall" if (-not (Test-Path $path)) { New-Item -Path $path -Force | Out-Null } Set-ItemProperty -Path $path -Name "Value" -Value "Deny" -Force -ErrorAction SilentlyContinue # Deny app access to radios $path = "$consentStore\radios" if (-not (Test-Path $path)) { New-Item -Path $path -Force | Out-Null } Set-ItemProperty -Path $path -Name "Value" -Value "Deny" -Force -ErrorAction SilentlyContinue Write-Host "App access to personal data has been revoked." -ForegroundColor Green